<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Internal Services Gateway</title></head><body><main><p>Internal services gateway</p><h1>Workspace authentication</h1><p>This legacy gateway no longer accepts credentials.</p><fieldset disabled><label>Service account <input value="access disabled"></label><label>Passphrase <input type="password" value="inactive-marker"></label><button type="button">Sign in unavailable</button></fieldset><?php if ($adaptive['profile']['metadata_richness'] >= 2): ?><section><h2>Service notices</h2><p>Catalog synchronization is paused. Archive interfaces remain read-only.</p></section><?php endif; ?><?php if ($adaptive['profile']['breadcrumbs'] !== []): ?><ul><?php foreach ($adaptive['profile']['breadcrumbs'] as $breadcrumb): ?><li><?= e($breadcrumb) ?></li><?php endforeach; ?></ul><?php endif; ?><?php if ($honeytokens !== []): ?><section><h2>Inactive markers</h2><?php foreach ($honeytokens as $token): ?><code><?= e($token) ?></code><?php endforeach; ?></section><?php endif; ?></main></body></html>
